\[\begin{align*}
&  0=\frac{\sum x_i}{p}-\frac{n-\sum x_i}{1-p}, \qquad \Rightarrow 0=\frac{\sum x_i -p\sum x_i -np+p\sum x_i}{p(1-p)}\\
& 0=\sum x_i-np, \qquad \hat{p}=\frac{\sum x_i}{n}
